pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score driven by remaining residual
    let mut score = (post_residual as f64) * 0.05;

    // New‑bin candidate handling
    if bin_residual == bin_capacity {
        // Prefer a new bin only when very few fitting bins or residual is significantly larger than average
        if fitting_bins_count <= 1 || post_residual > mean_residual as u32 + 15 {
            score += 4.5;
        } else {
            score += 1.5;
        }
        // Penalize when many bins are already open
        if open_bins_count > 10 {
            score += 7.0;
        } else if open_bins_count > 6 {
            score += 3.5;
        }
    }

    // Lookahead with the next item
    if next_item_size > 0 {
        let diff = post_residual as i32 - next_item_size as i32;
        if diff >= 0 {
            // Enough space for next item – reward small leftover
            score -= (diff.abs() as f64) * 0.15;
        } else {
            // Not enough space – heavy penalty that grows quadratically
            let deficit = -diff;
            score += 5.0 + (deficit as f64).powi(2) * 0.025;
        }
    }

    // Alignment with mean residual
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += mean_diff * 0.04;

    // Small residual reward
    if post_residual <= 1 {
        score -= 6.0;
    } else if post_residual <= 3 {
        score -= 3.5;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Usage ratio reward
    let usage_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if usage_ratio >= 0.95 {
        score -= 1.8;
    } else if usage_ratio >= 0.8 {
        score -= 0.9;
    }

    // Penalize large residuals when many bins are already open
    if open_bins_count >= 8 {
        score += (post_residual as f64).powi(2) * 0.0008;
    }

    // Progress‑based scaling
    let progress = step_index as f64 / total_items as f64;
    let progress_factor = 1.0 + (1.0 - progress).powi(2) * 0.015;
    score *= progress_factor;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 12.0;
    }

    // First bin incentive
    if open_bins_count == 0 {
        score -= 4.0;
    }

    // Endgame penalty for leftover space
    if total_items - step_index <= 3 {
        if post_residual > 0 {
            score += 3.0;
        }
    }

    // Dead space ratio penalty
    let dead_ratio = post_residual as f64 / bin_capacity as f64;
    if dead_ratio > 0.4 {
        score += dead_ratio * 10.0;
    }

    // Modulo penalty for residuals divisible by 7
    if post_residual % 7 == 0 {
        score -= 3.0;
    }

    score
}

