pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let waste = post_residual as f64;
    let usage_after = (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Base waste penalty
    let mut score = waste * waste * 0.0004;

    // Deviation from the global mean residual
    score += (waste - mean_residual).abs() * 0.015;

    // Utilization reward
    if usage_after > 0.97 {
        score -= 4.0;
    } else if usage_after > 0.93 {
        score -= 2.0;
    } else if usage_after > 0.90 {
        score -= 1.0;
    }

    // New‑bin decision logic
    if bin_residual == bin_capacity {
        // Open‑bin penalty based on how many bins are already open
        let open_penalty = if open_bins_count > 8 {
            14.0
        } else if open_bins_count > 6 {
            9.0
        } else if open_bins_count > 4 {
            5.0
        } else {
            1.0
        };
        score += open_penalty;

        // Prefer opening a new bin for very large items
        if item_size as f64 > 0.75 * bin_capacity as f64 {
            score -= 1.2;
        }

        // Reward almost full bins
        if waste <= 3.0 {
            score -= 0.7;
        }

        // Reward residual close to the mean
        if (waste - mean_residual).abs() <= 2.0 {
            score -= 0.5;
        }
    }

    // Look‑ahead for the next item
    if next_item_size > 0 {
        let diff = waste - next_item_size as f64;
        if diff >= 0.0 {
            if diff <= 2.0 {
                score -= diff * 0.35;
            } else if diff <= 8.0 {
                score -= diff * 0.20;
            } else {
                score -= diff * 0.12;
            }
        } else {
            score += (diff.abs() * diff.abs()) * 0.025;
        }
    }

    // Modulo tidy‑residual bonuses
    if post_residual % 5 == 0 {
        score -= 0.9;
    }
    if post_residual % 7 == 0 {
        score -= 1.0;
    }

    // Extra penalty when many bins are open
    if open_bins_count > 7 {
        score += waste * waste * 0.0002;
    }

    // Perfect‑fit bonus
    if waste == 0.0 {
        score -= 12.0;
    }

    // End‑of‑stream encouragement
    if total_items - step_index <= 2 && waste > 0.0 {
        score += 1.5;
    }

    // Small residual bonus
    if waste < 0.04 * bin_capacity as f64 {
        score -= 0.8;
    }

    // Fitting bins adjustment
    if fitting_bins_count > 0 {
        if waste > mean_residual + 5.0 {
            score += 1.5;
        }
    } else {
        if waste <= 5.0 {
            score -= 0.4;
        }
    }

    // Progress‑based scaling
    let progress = step_index as f64 / total_items as f64;
    let progress_factor = 1.0 + (1.0 - progress).powi(3) * 0.015;
    score * progress_factor
}

