        score -= 3.0;
    } else if usage_after > 0.90 {
        score -= 1.5;
    }

    // New‑bin decision logic
    if bin_residual == bin_capacity {
        // The bin is empty; decide whether to open a new one
        if fitting_bins_count > 0 {
