        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 0.9;
        }

        // Bonus if the new bin will be almost full after the item
        if residual <= 4.0 {
            score -= 0.5;
        }
    }

    // Look‑ahead for the next item
    if next_item_size > 0 {
        let diff = residual - next_item_size as f64;
        if diff >= 0.0 {
            // Space left for the next item – reward
            if diff <= 3.0 {
                score -= diff * 0.30;
            } else if diff <= 10.0 {
                score -= diff * 0.18;
            } else {
                score -= diff * 0.10;
            }
        } else {
            // Not enough space – quadratic penalty
            score += (diff.abs() * diff.abs()) * 0.022;
        }
    }

    // Modulo bonuses for tidy residuals
    if post_residual % 5 == 0 {
        score -= 0.8;
    }
    if post_residual % 9 == 0 {
        score -= 1.2;
    }

    // Extra penalty when many bins are open
    if open_bins_count > 5 {
        score += residual * residual * 0.00025;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 10.0;
    }

    // End‑of‑stream encouragement
    if total_items - step_index <= 3 && post_residual > 0 {
        score += 2.0;
    }

    // Small residual bonus
    if residual < (0.05 * bin_capacity as f64) {
        score -= 0.7;
    }

    // Progress‑based scaling
    let progress = step_index as f64 / total_items as f64;
    let progress_factor = 1.0 + (1.0 - progress).powi(2) * 0.02;
    score * progress_factor
