pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // ----- Base residual and ratio terms -----
    let mut score = (post_residual as f64).powi(2) * 0.002; // quadratic penalty for waste
    let ratio = (post_residual as f64) / (bin_capacity as f64);
    score += ratio * 3.0;                                 // higher ratio → higher cost

    // ----- Alignment with average residual -----
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += mean_diff * 0.04;

    // ----- New‑bin candidate handling -----
    if bin_residual == bin_capacity {
        // Prefer new bin when few fitting options or residual after placement is large
        if fitting_bins_count == 0 || post_residual > mean_residual as u32 + 8 {
            score += 4.5;
        } else {
            score += 1.2;
        }
        // Penalize for many open bins
        if open_bins_count > 10 {
            score += 7.0;
        } else if open_bins_count > 6 {
            score += 3.5;
        }
    }

    // ----- Lookahead with next item -----
    if next_item_size > 0 {
        let diff = post_residual as i32 - next_item_size as i32;
        if diff >= 0 {
            // room for next item – reward small leftover
            score -= (diff.abs() as f64) * 0.25;
        } else {
            // no room – heavy quadratic penalty
            score += 5.0 + ((-diff) as f64).powi(2) * 0.02;
        }
    }

    // ----- Usage ratio reward -----
    let used = bin_capacity - bin_residual;
    let usage_ratio = used as f64 / bin_capacity as f64;
    if usage_ratio >= 0.95 {
        score -= 1.8;
    } else if usage_ratio >= 0.8 {
        score -= 0.9;
    }

    // ----- Small residual incentive -----
    if post_residual <= 1 {
        score -= 4.0;
    } else if post_residual % 5 == 0 {
        score -= 1.5;
    }

    // ----- Late‑game penalty for leftover space -----
    if total_items - step_index <= 3 {
        if post_residual > 0 {
            score += 2.0;
        }
    }

    // ----- Progress‑based scaling -----
    let progress = step_index as f64 / total_items as f64;
    let progress_factor = 1.0 + (1.0 - progress).powi(2) * 0.015;
    score *= progress_factor;

    // ----- Perfect fit reward -----
    if post_residual == 0 {
        score -= 9.0;
    }

    // ----- First bin incentive -----
    if open_bins_count == 0 {
        score -= 2.5;
    }

    // ----- Coupling with number of fitting bins -----
    if fitting_bins_count > 5 {
        score -= 1.0 * ((fitting_bins_count as f64) / 10.0);
    }

    // ----- Open‑bin density scaling -----
    let open_factor = if open_bins_count > 8 {
        1.0 + (open_bins_count as f64 - 8.0) * 0.1
    } else {
        1.0
    };
    score *= open_factor;

    // ----- Fit ratio reward (small leftover relative to item size) -----
    let fit_ratio = (post_residual as f64 + 1.0) / (item_size as f64 + 1.0);
    score -= fit_ratio.powi(2) * 0.3;

    // ----- Large item penalty when residual is small -----
    if item_size > (bin_capacity / 2) {
        score += (post_residual as f64) * 0.01;
    }

    score
}
